<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { api } from '../api';

const router = useRouter();
const home = ref<any>(null);
const loading = ref(true);
const error = ref('');
const reflection = ref('');
const advanced = ref({ decisionQuestion: '', decisionOptions: '', cooldownTitle: '', cooldownReason: '', cooldownHours: 24, handoffRecipient: '', handoffChannel: '', handoffSummary: '', supportTitle: '', supportPlan: '', memoryCategory: 'journey', memoryContent: '', memoryDays: 30 });
const cooldowns = ref<any[]>([]);
const handoffs = ref<any[]>([]);
const memories = ref<any[]>([]);
const advancedBusy = ref(false);

async function loadAdvanced() {
  const results = await Promise.allSettled([api.get<any>('/api/v1/cooldown'), api.get<any>('/api/v1/handoffs'), api.get<any>('/api/v1/me/memories')]);
  cooldowns.value = results[0].status === 'fulfilled' ? results[0].value.items ?? [] : [];
  handoffs.value = results[1].status === 'fulfilled' ? results[1].value.items ?? [] : [];
  memories.value = results[2].status === 'fulfilled' ? results[2].value.items ?? [] : [];
}
async function load() { loading.value = true; try { home.value = (await api.get<any>('/api/v1/tonight')).item; await loadAdvanced(); } catch (cause: any) { error.value = cause?.message ?? '行动加载失败'; } finally { loading.value = false; } }
async function checkin(id: string, status: 'completed' | 'missed' = 'completed') { try { await api.post(`/api/v1/actions/${id}/checkin`, { status, reflection: reflection.value.trim() || (status === 'completed' ? '我完成了今天约定的小一步。' : '这一步今天还没有完成，我记录下了原因。') }); reflection.value = ''; await load(); } catch (cause: any) { error.value = cause?.message ?? '打卡失败'; } }
async function runAdvanced(task: () => Promise<void>) { advancedBusy.value = true; error.value = ''; try { await task(); } catch (cause: any) { error.value = cause?.message ?? '保存失败，请检查隐私设置'; } finally { advancedBusy.value = false; } }
async function createDecision() { if (!advanced.value.decisionQuestion.trim()) return; await runAdvanced(async () => { await api.post('/api/v1/decisions', { journeyId: home.value?.journey?.id, question: advanced.value.decisionQuestion, options: advanced.value.decisionOptions.split(/[,，]/).map((item) => item.trim()).filter(Boolean) }); advanced.value.decisionQuestion = ''; advanced.value.decisionOptions = ''; }); }
async function createCooldown() { if (!advanced.value.cooldownTitle.trim()) return; await runAdvanced(async () => { await api.post('/api/v1/cooldowns', { title: advanced.value.cooldownTitle, reason: advanced.value.cooldownReason, hours: advanced.value.cooldownHours }); advanced.value.cooldownTitle = ''; advanced.value.cooldownReason = ''; await loadAdvanced(); }); }
async function createHandoff() { if (!advanced.value.handoffRecipient.trim() || !advanced.value.handoffChannel.trim() || !advanced.value.handoffSummary.trim()) { error.value = '请补全交接对象、联系渠道和说明'; return; } await runAdvanced(async () => { const response = await api.post<any>('/api/v1/handoffs', { journeyId: home.value?.journey?.id, recipient: advanced.value.handoffRecipient, channel: advanced.value.handoffChannel, summary: advanced.value.handoffSummary }); handoffs.value.unshift(response.item); advanced.value.handoffRecipient = ''; advanced.value.handoffChannel = ''; advanced.value.handoffSummary = ''; }); }
async function shareHandoff(id: string) { await runAdvanced(async () => { const response = await api.post<any>(`/api/v1/handoffs/${id}/share`); const index = handoffs.value.findIndex((item) => item.id === id); if (index >= 0) handoffs.value[index] = response.item; }); }
async function saveSupportPlan() { if (!advanced.value.supportPlan.trim()) return; await runAdvanced(async () => { await api.put('/api/v1/me/support-plan', { journeyId: home.value?.journey?.id, title: advanced.value.supportTitle || '我的现实支持计划', plan: { steps: advanced.value.supportPlan } }); advanced.value.supportPlan = ''; }); }
async function saveMemory() { if (!advanced.value.memoryContent.trim()) return; await runAdvanced(async () => { const response = await api.post<any>('/api/v1/memory', { journeyId: home.value?.journey?.id, category: advanced.value.memoryCategory, content: advanced.value.memoryContent, days: advanced.value.memoryDays }); memories.value.unshift(response.item); advanced.value.memoryContent = ''; }); }
async function removeMemory(id: string) { await runAdvanced(async () => { await api.delete(`/api/v1/me/memories/${id}`); memories.value = memories.value.filter((item) => item.id !== id); }); }
onMounted(load);
</script>
<template>
  <section class="page goodnight-page modern-page action-page">
    <header class="modern-hero compact"><div class="status-row"><span>23:17</span><span>92</span></div><p class="eyebrow">ACTION LOOP</p><h1>把想法变成一小步</h1><p>行动不是证明自己，是给现实一个可以观察的回应。</p></header>
    <p v-if="error" class="error-text">{{ error }}</p><p v-if="loading" class="soft-note">正在读取行动...</p>
    <template v-else>
      <section class="modern-card" v-if="home?.journey"><span class="section-kicker">当前旅程</span><div class="card-heading"><h2>{{ home.journey.title }}</h2><button class="text-button" @click="router.push(`/pages/journey/detail?id=${home.journey.id}`)">查看时间线</button></div><p>{{ home.journey.summary || '先完成一个可观察的小行动。' }}</p></section>
      <section class="modern-card"><div class="card-heading"><h2>待完成的行动</h2><span class="count-badge">{{ home?.activeActions?.length ?? 0 }}</span></div><label class="reflection-field">这一步后来怎么样？<textarea v-model="reflection" maxlength="800" placeholder="可以写做到、没做到，或遇到的阻碍" /></label><div v-if="home?.activeActions?.length" class="commitment-list"><article v-for="action in home.activeActions" :key="action.id"><div><strong>{{ action.title }}</strong><small>{{ action.description || '完成后回来写下真实结果' }}</small></div><div class="checkin-actions"><button class="primary-small" @click="checkin(action.id, 'completed')">完成并回顾</button><button class="secondary-small" @click="checkin(action.id, 'missed')">没做到</button></div></article></div><p v-else class="empty-note">当前没有待完成行动。打开今晚页面，先建立一段旅程。</p><button v-if="!home?.journey" class="outline-button full" @click="router.push('/pages/tonight/index')">去今晚建立旅程</button></section>
      <section v-if="home?.dueCheckins?.length" class="modern-card"><div class="card-heading"><h2>待回顾</h2><span class="count-badge">{{ home.dueCheckins.length }}</span></div><button v-for="item in home.dueCheckins" :key="item.id" class="checkin-row" @click="checkin(item.commitmentId)"><span>回顾这次行动</span><b>›</b></button></section>
      <details class="modern-card advanced-tools"><summary>把支持带回现实</summary><p class="soft-note">这些记录只在你明确保存后产生。长期保存前，请先检查隐私设置。</p><div class="tool-grid"><form @submit.prevent="createDecision"><h3>决策记录</h3><input v-model="advanced.decisionQuestion" placeholder="这次要做什么决定？" required /><input v-model="advanced.decisionOptions" placeholder="选项，以逗号分开" /><button class="outline-button full" :disabled="advancedBusy">保存决策</button></form><form @submit.prevent="createCooldown"><h3>冷静箱</h3><input v-model="advanced.cooldownTitle" placeholder="暂缓处理的事项" required /><input v-model="advanced.cooldownReason" placeholder="为什么先暂停？" /><input v-model.number="advanced.cooldownHours" type="number" min="1" max="168" placeholder="小时" /><button class="outline-button full" :disabled="advancedBusy">加入冷静箱</button></form><form @submit.prevent="createHandoff"><h3>现实交接</h3><input v-model="advanced.handoffRecipient" placeholder="交接给谁" required /><input v-model="advanced.handoffChannel" placeholder="联系渠道" required /><textarea v-model="advanced.handoffSummary" placeholder="希望对方知道什么" required /><button class="outline-button full" :disabled="advancedBusy">保存交接</button></form><form @submit.prevent="saveSupportPlan"><h3>支持计划</h3><input v-model="advanced.supportTitle" placeholder="计划名称（可选）" /><textarea v-model="advanced.supportPlan" placeholder="遇到困难时可联系谁、做什么" required /><button class="outline-button full" :disabled="advancedBusy">保存支持计划</button></form><form @submit.prevent="saveMemory"><h3>有限记忆</h3><input v-model="advanced.memoryCategory" placeholder="记忆分类" required /><textarea v-model="advanced.memoryContent" placeholder="只保存明确同意留下的信息" required /><input v-model.number="advanced.memoryDays" type="number" min="1" max="90" placeholder="保留天数" /><button class="outline-button full" :disabled="advancedBusy">保存有限记忆</button></form></div><div v-if="cooldowns.length || handoffs.length || memories.length" class="saved-tools"><h3>已保存的现实记录</h3><p v-for="item in cooldowns" :key="item.id">冷静箱：{{ item.title }} · {{ item.status }}</p><p v-for="item in handoffs" :key="item.id">交接：{{ item.recipient }} · {{ item.status }} <button class="text-button" v-if="item.status === 'ready'" @click="shareHandoff(item.id)">确认已分享</button></p><p v-for="item in memories" :key="item.id">记忆：{{ item.content }} <button class="text-button" @click="removeMemory(item.id)">删除</button></p></div><button class="text-button settings-link" @click="router.push('/pages/settings/privacy')">打开隐私设置</button></details>
    </template>
  </section>
</template>
<style scoped>
.modern-page { display:grid; gap:16px; padding:0 14px 150px; }.modern-hero {position:relative; min-height:214px; padding:28px 12px 24px; overflow:hidden; border-radius:0 0 34px 34px; background:linear-gradient(135deg,#f8f4e9,#e9f0df)}.modern-hero.compact{min-height:184px}.modern-hero::after{position:absolute;right:-14px;bottom:-18px;width:190px;height:190px;background:url('../assets/goodnight/tree-top-cutout.png') center/cover no-repeat;opacity:.35;content:'';pointer-events:none}.modern-hero .status-row{position:relative;z-index:1;display:flex;justify-content:space-between;font-weight:700}.eyebrow,.section-kicker{color:var(--gn-green);font-size:12px;letter-spacing:.06em}.modern-hero h1{position:relative;z-index:1;max-width:300px;margin:34px 0 8px;color:var(--gn-green-dark);font-family:var(--gn-font-display);font-size:32px;line-height:1.28}.modern-hero p:last-child{position:relative;z-index:1;margin:0;color:var(--gn-subtext)}.modern-card{border:1px solid var(--gn-border);border-radius:var(--gn-radius-card);background:var(--gn-card);box-shadow:var(--gn-shadow-card);padding:22px}.modern-card h2{margin:6px 0 8px;color:var(--gn-text);font-size:21px}.modern-card p{color:var(--gn-subtext);line-height:1.7}.card-heading{display:flex;justify-content:space-between;align-items:start;gap:10px}.text-button,.outline-button{border:0;background:transparent;color:var(--gn-green);font:inherit;cursor:pointer}.count-badge{min-width:24px;padding:4px 8px;border-radius:99px;background:var(--gn-green-light);color:var(--gn-green-dark);text-align:center}.reflection-field{display:grid;gap:7px;margin:14px 0;color:var(--gn-subtext);font-size:13px}.reflection-field textarea{min-height:74px;resize:vertical;box-sizing:border-box;width:100%;border:1px solid var(--gn-border);border-radius:14px;padding:10px 12px;background:#fffdf8;font:inherit;line-height:1.5}.commitment-list{display:grid;gap:10px}.commitment-list article{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid var(--gn-border)}.commitment-list strong,.commitment-list small{display:block}.commitment-list small{margin-top:5px;color:var(--gn-subtext);line-height:1.5}.checkin-actions{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}.primary-small,.secondary-small{flex:0 0 auto;border:0;border-radius:14px;padding:10px 12px;background:var(--gn-green);color:#fff;cursor:pointer;font:inherit}.secondary-small{background:transparent;border:1px solid var(--gn-border);color:var(--gn-green-dark)}.checkin-row{display:flex;width:100%;justify-content:space-between;border:0;border-bottom:1px solid var(--gn-border);background:transparent;padding:14px 0;color:var(--gn-text);font:inherit;text-align:left}.empty-note{margin-bottom:0}.full{width:100%;margin-top:14px;padding:12px;border:1px solid var(--gn-border);border-radius:15px}.error-text{margin:0 4px;color:var(--gn-danger)}.advanced-tools summary{cursor:pointer;color:var(--gn-green-dark);font-size:18px;font-weight:700}.advanced-tools .soft-note{font-size:13px}.tool-grid{display:grid;gap:12px}.tool-grid form{display:grid;gap:8px;padding-top:12px;border-top:1px solid var(--gn-border)}.tool-grid h3,.saved-tools h3{margin:0;color:var(--gn-green-dark);font-size:16px}.tool-grid input,.tool-grid textarea{width:100%;box-sizing:border-box;border:1px solid var(--gn-border);border-radius:12px;padding:10px;background:#fffdf8;font:inherit}.tool-grid textarea{min-height:72px;resize:vertical;line-height:1.5}.saved-tools{margin-top:16px;padding-top:12px;border-top:1px solid var(--gn-border)}.saved-tools p{margin:8px 0;font-size:13px}.settings-link{margin-top:14px}
</style>
